p20.pick_up_tip()
d = 0.0
step = 10.0
while True:
    d += step
    p20.move_to(rack3["A1"].top(z=-d))      # descend d mm below the well top
    fb = probe()                             # 远 / 近 / 很近了 / 快贴底 / 触底风险
    if fb == "远":
        step = 10.0
    elif fb == "近":
        step = 5.0
    elif fb == "很近了":
        step = 1.0
    elif fb == "快贴底":
        break
    else:
        raise RuntimeError("probe overshot the tube bottom")
p20.aspirate(PEPTIDE_VOL_UL, rack3["A1"].top(z=-d))
p20.drop_tip()
